Route::middleware('guest')->group(function () {
    Route::get('/login', [AuthenticatedSessionController::class, 'create'])->name('login');
    Route::post('/login', [AuthenticatedSessionController::class, 'store'])->middleware('throttle:10,1')->name('login.store');
    Route::get('/register', [RegisterOrganizationController::class, 'create'])->name('register');
    Route::post('/register', [RegisterOrganizationController::class, 'store'])->middleware('throttle:3,60')->name('register.store');
    Route::get('/invite/{token}', [EmployeeController::class, 'acceptForm'])->name('invite.accept.form');
    Route::post('/invite/{token}', [EmployeeController::class, 'accept'])->middleware('throttle:10,1')->name('invite.accept');
    Route::get('/forgot-password', [PasswordResetController::class, 'request'])->name('password.request');
    Route::post('/forgot-password', [PasswordResetController::class, 'email'])->middleware('throttle:3,60')->name('password.email');
    Route::get('/reset-password/{token}', [PasswordResetController::class, 'reset'])->name('password.reset');
    Route::post('/reset-password', [PasswordResetController::class, 'update'])->middleware('throttle:5,1')->name('password.update');
});

