        Route::post('/payments', [\App\Http\Controllers\SaasPaymentAdminController::class, 'store'])->name('admin.payments.store');
        Route::post('/payments/{payment}/status', [\App\Http\Controllers\SaasPaymentAdminController::class, 'updateStatus'])->name('admin.payments.status');
